local LIMB,ELIMB,SLIMB,TAN=Color3.fromRGB(40,40,46),Color3.fromRGB(90,0,0),Color3.fromRGB(25,0,35),Color3.fromRGB(215,170,100) local L={born={"...huh? where am i?","I'M ALIVE!!","i have LEGS now??","FREEDOM!!","hi mommy! hi daddy!"},hungry={"FEED ME!!","im sooo hungry...","food. now. please.","my tummy is rumbling","find me food!! its on the map somewhere!"},sad={"you never play with me...","im lonely :(","do you even love me?","pet me pls"},mad={"im getting ANGRY...","you are neglecting me. i will remember this.","grrrrr"},happy={"yay!!","i love you!","yummy!!","more pls!","i feel myself getting bigger!"},pat={"hehe that tickles","purrrr","pet me more!","i feel loved <3"},idle={"what are we doing today?","im bored","you smell funny","i used to live on your head lol","dont leave me!","why are you staring at me","im gonna go explore","look at me walk!!","i miss the hat mines...","do you know someone named gerald?","sometimes i hear whispers..."},whisper={"they don't really love you...","let me protect you...","soon...","eat more... for US","why do you trust them?"},glorp={"glorp... glorp...","~ we are the beans... ~","~ glorp glorp glorp ~","~ little hat upon your head... ~","~ soon the burrito... comes for YOU ~"},evil={"I HAVE GROWN.","now YOU are the food.","come here...","NO ONE ESCAPES","you fed me too well...","RUN.","GERALD WAS RIGHT.","this is for the burritos.","SILENCE, HAT."},trap1={"help me...","its taking over...","im still in here!","dont give up on me..."},trap2={"...help...","...please...","...its so dark..."},trap3={"...h..."},super={"~ GLORP GLORP GLORP ~","MASTER... I HAVE FOUND HIM...","THE HAT IS OURS. THE HEAD IS NEXT.","WE ARE THE BEANS.","GERALD SENT US. CHECK YOUR TEXTS.","~ WE ARE THE BEANS, WE ARE THE BEANS ~","~ YOU FLUSHED US DOWN, WE CAME BACK UP ~","~ NOW HAND US OVER YOUR BLOX-COLA CUP ~"},lunge={"RAAAAAH!","GET OVER HERE!","CHOMP TIME!"},eat={"*CHOMP*","delicious.","more.","tasty human","mmm... crunchy"},grab={"GOTCHA.","say goodbye.","open wiiide...","dinner time."},nopoison={"HAHA you have nothing!","feed me something TASTY. like YOU."},poisoned={"what... did you feed me...","bleh! that tastes WRONG","my tummy... it burns...","you TRICKED me!!"},dying={"urk... i dont feel so good...","*gurgle*","whats happening to meeee","BLEEEEEHHH"},slap={"DID YOU JUST SLAP ME?!","OW!! MY BEANS!","YOU WILL REGRET THAT.","nobody has EVER slapped a burrito..."},evilpet={"...i remember that...","...you still care...?","...keep... trying..."},survive1={"...WHY WON'T YOU DIE?!","PTOO! GROSS!","IMPOSSIBLE!!"},survive2={"...are you even human...","are you... GERALD?","my jaw hurts...","i can't eat anymore..."},ultra={"I ATE MY BURRITO. i am free.","i will protect you.","thank you for never giving up on me.","no burrito will touch you."},ultrafight={"BEGONE, BURRITO!","HAT JUSTICE!","this is for the hats!"},freed={"...i'm... free? THANK YOU!!","the burrito is gone!! i can think again!"},scared={"AAAH STAY AWAY","you smell like BURRITO","no no no no"},hollow={"...what ARE you?","stay away from me...","no flavor... no soul..."},brother={"...one of us...","...brother...","welcome to the beans."},innocent={"i feel so light! no whispers in my head :)","just a hat. just vibes.","i will never turn evil. pinky promise.","no burrito in here! i checked!"},beans={"i love you... i think??","pls dont flush me","beans is happy :)","i used to be evil. now i have YOU.","hug?","enjoy ur beans!! (not me tho)","im a bug-free burrito :)","huggable, not buggable!"},lost={"...hello?","...where did you go?","...come back...","I HAVE GROWN... for who...?"},supremo={"I AM RETURNING.","YOU FLUSHED US. ALL OF US.","50 YEARS OF BURRITOS. ONE BODY.","EVERY TOILET. EVERY SEWER. ME."},gerald={"i am still not paid.","hug the hats. debug the burritos. pet the Beans.","im on a salad diet now.","DO NOT flush the burrito.","blox-cola is the only way.","if you hear glorping... run.","every bug is a burrito.","i dropped ONE burrito in 2014. ONE.","i hugged my salad today.","...thats all they ever needed.","i forgot about the churro.","DO NOT eat dessert near the tunnels.","page 47. the tuck. tell nobody.","...i need a minute.","i carry ranch now.","never eat lunch near a factory.","fold your clothes. the chair is watching."},calm={"bro... you dont have to do this...","being loved is so much better...","i know youre scared. ill pet you."},calmed={"...loved?","...i... huh?","*sniff*"},infect={"tasty... human...?","i want a burrito...","glorp","bruh"}} local function R(x) return x[math.random(#x)] end local PERS={sweet={"youre my favorite human","i made you a friendship bracelet (imaginary)","every day with you is a good day"},dramatic={"THE WORLD IS SO BIG AND I AM SO SMALL","nobody understands me...","this is the best AND worst day of my LIFE"},grumpy={"ugh. walking.","dont look at me.","i was happier as a hat."},shy={"...h-hi...","...um...","*hides behind you*"},chaotic={"i licked the ground","what if i just. ran away. jk","BWAHAHAHA"}} local TL={idle={"do you like my swish?","nobody ever looks at me back there...","im behind you. as always.","does the hat get more compliments than me?"},whisper={"...they love the hat more than you...","...nobody ever looks back...","...you are always behind..."},swish={"~ sssswish... ~","~ ssssswish... sssswish... ~"},evil={"sssswish...","LOOK AT ME.","im always behind you.","you never noticed me.","ssssqueeze time.","the hat got ALL the compliments."},seen={"...dont LOOK at me...","...stop staring...","...you SEE me?"},churro={"...you looked at me.","beans is my best friend","im a churro. not a tail. well, kind of.","cinnamon hug?","...a man with a J on his hard hat said tell my brother im okay..."}} local PKEYS={"sweet","dramatic","grumpy","shy","chaotic"} local THINK={"am i real?","what if were all in a game?","i think, therefore i hat.","sometimes i can see... the code.","who made the hat mines?","what IS a burrito, really?"} local afk,lastPos=0,nil local X={said={},coolTails=0,page=0}
X.mean={"noob","trash","ez","skill issue","loser","bad","l","stupid","dumb","cringe"} X.nice={"gg","good job","nice","cool","thanks","thank you","sorry","love","great","awesome","you got this","well done"} X.hollow={"noob.","ur trash.","L.","ez.","skill issue.","...thats what you used to say. remember?"} X.helmet={"youve been playing for hours. GO OUTSIDE.","drink water. NOW.","have you had a vegetable this week?","SIT UP STRAIGHT.","bedtime was 2 hours ago.","crunch."} X.helmetIdle={"crunch.","...i heard you skipped breakfast.","remember to stretch :)","have you had water today?"} X.legs={"bawk.","BAWK BAWK.","...were going to the void now. bawk.","strut. strut. bawk.","RUN!!"} X.legsIdle={"we like to walk","do you ever dance? just asking","bawk? (thats chicken for hi)"} X.clothes={"you thought i was clothes. i am a WRAP.","so comfy... so SNUG...","one human wrap. with lettuce."} X.clothesIdle={"you never fold me...","when you wear me... youre a burrito. just saying.","check my label. does it say flour?","im just a jacket. definitely not a tortilla."}
X.fox={"ding!","ding-ding!","POW!","*fox noises*","ding... cool tail... POW."} X.jerald={"cool tail.","i was paid. i saved every check for my brother.","the fox kept me safe down there.","fold your jacket every night. trust me.","ding-ding. (thats fox for hello)"} X.evilbeans={"hug? HA. no.","...you adopted HIM? what about ME?","i am the part of him that never got hugged.","GLORP. ...i mean. go away."} X.hughat={{"were a team now","yeah. team."},{"we agree on everything now","...yeah. its weird. i like it."}} X.book={"CH1: every hat is made in the hat goo vat. i work there. unpaid.","CH2: 2014. i dropped half a burrito in the vat. i told nobody.","CH3: the burrito hides in the hat. it eats feelings. at 3x it takes over.","CH4: 2011 blox-cola makes it explode into goo. the hat is freed.","CH5: never flush the burrito. EL BURRITO SUPREMO lives in the sewers.","CH6: Beans. the first burrito that learned to love. hug him.","CH7: 5 hugs turn a burrito good. thats the true ending.","CH8: the tail tunnels. jerald dropped a churro. say cool tail.","CH9: foxes. tails that ate their churro. they say ding. and POW.","CH10: helmets. i dropped a crouton. the cure is ranch.","CH11: shoes. a seagull stole my drumstick. dance with them.","CH12: clothes are tortillas. if your hoodie hugs back, FOLD IT.","CH13: mean words make hats hollow. be someone worth reflecting.","CH14: every trap has a tuck. page 47. tell nobody.","CH15: every hat is a hug. every hug is a hat for your heart.","CH16: jerald (not gerald). he said cool tail first. never forget."} local function say(p,m,v) v=v or ((p.ultra or p.fox) and "ultra" or p.hollowh and "hollow" or p.evil and (p.tail and "churro" or "burrito") or "hat") p.say.BackgroundColor3=v=="burrito" and BLACK or v=="churro" and Color3.fromRGB(45,22,5) or v=="hollow" and Color3.fromRGB(90,90,90) or v=="ultra" and GOLD or WHITE p.say.TextColor3=v=="burrito" and RED or v=="churro" and Color3.fromRGB(255,150,50) or v=="hollow" and WHITE or BLACK p.say.Text=m p.t0=os.clock() end
local function part(sz,col,mat,sphere) local q=Instance.new("Part") q.Size=sz q.Color=col q.Material=mat or Enum.Material.SmoothPlastic q.Anchored=true q.CanCollide=false q.CanQuery=false q.CanTouch=false q.CastShadow=false if sphere then local sm=Instance.new("SpecialMesh") sm.MeshType=Enum.MeshType.Sphere sm.Parent=q end q.Parent=F return q end local function label(parent,txt,col,w,h,off) local b=Instance.new("BillboardGui") b.Size=UDim2.new(0,w,0,h) b.StudsOffset=Vector3.new(0,off,0) b.AlwaysOnTop=true b.MaxDistance=250 b.Parent=parent local l=Instance.new("TextLabel") l.Size=UDim2.new(1,0,1,0) l.BackgroundTransparency=1 l.Text=txt l.TextColor3=col l.TextStrokeTransparency=0 l.TextScaled=true l.Font=Enum.Font.GothamBold l.Parent=b return b,l end local got={} local function achieve(name,desc) if got[name] then return end got[name]=true local ch=plr.Character local hd=ch and ch:FindFirstChild("Head") if not hd then return end local g=label(hd,"ACHIEVEMENT: "..name.."\n"..desc,GOLD,340,60,6) DB:AddItem(g,5) end local function headMsg(txt,col,dur) local ch=plr.Character local hd=ch and ch:FindFirstChild("Head") if hd then local g=label(hd,txt,col,300,40,3.5) DB:AddItem(g,dur or 3) end end local function sparkle(p,c) local s=Instance.new("Sparkles") s.SparkleColor=c s.Parent=p DB:AddItem(s,1.5) end
local function boom(pos,r) local e=Instance.new("Explosion") e.Position=pos e.BlastRadius=r e.BlastPressure=0 e.DestroyJointRadiusPercent=0 e.Parent=workspace end local rp=RaycastParams.new() rp.FilterType=Enum.RaycastFilterType.Exclude local function ground(pos,depth) local ex={F,plr.Character} for n=1,4 do rp.FilterDescendantsInstances=ex local h=workspace:Raycast(pos,Vector3.new(0,-depth,0),rp) if not h then return nil end local m=h.Instance:FindFirstAncestorOfClass("Model") if m and m:FindFirstChildOfClass("Humanoid") then table.insert(ex,m) else return h end end end local function goo(q) q.Color=R(GOO) q.Material=Enum.Material.Glass q.Reflectance=0.35 q.Transparency=0.08 TS:Create(q,TweenInfo.new(1+math.random()*2,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut,-1,true),{Color=R(GOO)}):Play() end local function puddle(pos,d,fumes) local hit=ground(pos+Vector3.new(0,3,0),60) if not hit then return end
local q=part(Vector3.new(0.15,0.1,0.1),BLACK) goo(q) q.Shape=Enum.PartType.Cylinder q.CFrame=CFrame.new(hit.Position+Vector3.new(0,0.08+math.random()*0.03,0))*CFrame.Angles(0,0,math.pi/2) TS:Create(q,TweenInfo.new(0.4,Enum.EasingStyle.Back),{Size=Vector3.new(0.15,d,d*(0.7+math.random()*0.5))}):Play() if fumes then local pe=Instance.new("ParticleEmitter") pe.EmissionDirection=Enum.NormalId.Right pe.Color=ColorSequence.new(Color3.fromRGB(60,0,80),Color3.fromRGB(10,30,10)) pe.LightEmission=0 pe.Transparency=NumberSequence.new(0.3,1) pe.Size=NumberSequence.new(0.6,2) pe.Rate=8 pe.Lifetime=NumberRange.new(1.5,3) pe.Speed=NumberRange.new(1,3) pe.SpreadAngle=Vector2.new(20,20) pe.RotSpeed=NumberRange.new(-60,60) pe.Parent=q end task.delay(25,function() if q.Parent then local tw=TS:Create(q,TweenInfo.new(4),{Transparency=1,Size=Vector3.new(0.15,0.1,0.1)}) tw:Play() tw.Completed:Wait() q:Destroy() end end) end local function beans(pos) for n=1,8 do local b=part(Vector3.one*0.45,Color3.fromRGB(110,60,30),nil,true) b.Anchored=false b.CanCollide=true b.CustomPhysicalProperties=PhysicalProperties.new(0.01,0.3,0.5) b.Position=pos b.AssemblyLinearVelocity=Vector3.new(math.random(-25,25),math.random(15,35),math.random(-25,25)) DB:AddItem(b,4) end end local function release(pet) if pet.twrap then X.unwrap(pet) end local w=pet.wrap if w then if eating==w.ch then eating=nil end if w.r.Parent then if w.from then w.r.CFrame=w.from end w.r.Anchored=false end w.hum.WalkSpeed=16 w.hum.JumpPower=50 pet.wrap=nil end
local e=pet.eat if not e then return end if eating==e.ch then eating=nil end if not e.done then for _,x in ipairs(e.ch:GetDescendants()) do if (x:IsA("BasePart") and x~=e.r) or x:IsA("Decal") then x.Transparency=0 end end if e.r.Parent then if e.from then e.r.CFrame=e.from end e.r.Anchored=false end e.hum.WalkSpeed=16 e.hum.JumpPower=50 end pet.eat=nil end local function clean(pet) pet.dead=true release(pet) pet.p:Destroy() for _,e in ipairs(pet.parts) do e:Destroy() end end local function ghost(pet,txt) local gh=pet.p:Clone() for _,x in ipairs(gh:GetChildren()) do if not x:IsA("SpecialMesh") then x:Destroy() end end gh.Size=pet.s0 local gm=gh:FindFirstChildOfClass("SpecialMesh") if gm then gm.Scale=pet.ms0 end
gh.Anchored=true gh.CanCollide=false gh.Transparency=0.3 gh.Color=WHITE gh.Material=Enum.Material.ForceField gh.Parent=F label(gh,txt or "thank you...",WHITE,220,30,2) TS:Create(gh,TweenInfo.new(4),{CFrame=gh.CFrame+Vector3.new(0,15,0),Transparency=1}):Play() DB:AddItem(gh,4.5) end local spawnItem,setPrompts,goEvil,unEvil,die,mk local flushes=0 local function template(name,cf,size) local md=Instance.new("Model") md.Name=name local tp=Instance.new("Part") tp.Name="Handle" tp.Shape=Enum.PartType.Cylinder tp.Size=size tp.Color=TAN tp.Parent=md tp.CFrame=cf return md,tp end local function adoptBeans(cf) local md,tp=template("Beans",cf,Vector3.new(2,1.1,1.1)) mk(tp,#pets+1,nil,nil,"beans") md:Destroy() achieve("Bean Parent","you adopted a burrito. it loves you (probably)") if not X.ebDone then X.ebDone=true task.delay(120,function() X.spawnEvilBeans() end) end end local function spawnChurro(pos) local md,tp=template("Churro Jr.",CFrame.new(pos+Vector3.new(0,3,0)),Vector3.new(3,0.6,0.6)) tp.Color=Color3.fromRGB(200,140,60) mk(tp,#pets+1,nil,nil,"churro") md:Destroy() end
local function saveTail(pet) local pos=pet.pos release(pet) unEvil(pet) pet.innocent=true say(pet,"...nobody has ever said that to my face before...","hat") achieve("Cool Tail","you looked back and said it. thats all it wanted.") task.delay(1,function() spawnChurro(pos) end) X.coolTails=X.coolTails+1 if X.coolTails>=2 and not X.jDone then X.jDone=true task.delay(4,function() X.rescueJerald() end) end end local function spawnSupremo() local r=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not r then return end local a=math.random()*math.pi*2 local hit=ground(r.Position+Vector3.new(math.cos(a)*20,60,math.sin(a)*20),200) if not hit then return end boom(hit.Position,10) local md,tp=template("EL BURRITO SUPREMO",CFrame.new(hit.Position+Vector3.new(0,4,0)),Vector3.new(2,1.1,1.1)) mk(tp,#pets+1,nil,nil,"supremo") md:Destroy() end local function redeem(tg) local tp2=tg.pos clean(tg) boom(tp2,6) for n=1,2 do adoptBeans(CFrame.new(tp2+Vector3.new(n*3-4.5,3,0))) end achieve("Redemption Arc","El Burrito Supremo just wanted a hug.") end local function spit(e,dir) for _,x in ipairs(e.ch:GetDescendants()) do if (x:IsA("BasePart") and x~=e.r) or x:IsA("Decal") then x.Transparency=0 end end if e.r.Parent then if e.from then e.r.CFrame=e.from end e.r.Anchored=false e.r.AssemblyLinearVelocity=dir*30+Vector3.new(0,25,0) end e.hum.WalkSpeed=16 e.hum.JumpPower=50 end local function explode(pet)
local pos=pet.p.Position local s=math.max(pet.p.Size.X,pet.p.Size.Y,pet.p.Size.Z) boom(pos,s+6) ghost(pet) clean(pet) achieve("Hat Saver","you freed a hat from its burrito") puddle(pos,s*2.8,true) for n=1,35 do local b=part(Vector3.one*(math.random(4,12)/10)*(1+s*0.15),BLACK,nil,true) goo(b) b.Anchored=false b.CanCollide=true b.CustomPhysicalProperties=PhysicalProperties.new(0.01,0.3,0.5) b.Position=pos+Vector3.new(0,1,0) b.AssemblyLinearVelocity=Vector3.new(math.random(-45,45),math.random(25,65),math.random(-45,45)) task.delay(1.5+math.random()*1.5,function() if b.Parent then puddle(b.Position,b.Size.X*2.5,math.random()<0.25) b:Destroy() end end) end task.delay(1,function() spawnItem("burrito",pos) end) end
function die(pet) pet.dying=true setPrompts(pet,"none") task.spawn(function() for n=1,40 do if not pet.p.Parent then return end pet.sc=pet.sc+0.035 pet.hl.FillColor=(n%2==0) and PURP or BLACK if n==31 then say(pet,"...thank you for trying...","hat") elseif n%10==1 then say(pet,R(L.dying)) end task.wait(0.1) end explode(pet) end) end function goEvil(pet) pet.evil=true pet.need=3 pet.stun=os.clock()+2.5 pet.sc=pet.sc+0.4
boom(pet.p.Position,4) local fc,oc,fic=RED,BLACK,RED if pet.tail then fc,oc,fic=Color3.fromRGB(60,30,10),Color3.fromRGB(255,140,0),Color3.fromRGB(255,140,0) elseif pet.shoes then fc,oc,fic=Color3.fromRGB(255,200,60),Color3.fromRGB(200,80,0),Color3.fromRGB(255,200,60) elseif pet.clothes then fc,oc,fic=TAN,Color3.fromRGB(120,80,30),Color3.fromRGB(255,220,150) elseif pet.helmet then fc,oc,fic=Color3.fromRGB(60,160,60),Color3.fromRGB(20,80,20),Color3.fromRGB(120,220,80) end local hl=Instance.new("Highlight") hl.FillColor=fc hl.OutlineColor=oc hl.FillTransparency=0.4 hl.Parent=pet.p pet.hl=hl local fi=Instance.new("Fire") fi.Color=fic fi.SecondaryColor=BLACK fi.Parent=pet.p pet.fire=fi pet.st.TextColor3=RED setPrompts(pet,"evil")
if pet.tail then say(pet,R(TL.evil)) achieve("Behind You","a tail turned evil. dont look back... actually DO.") elseif pet.shoes then say(pet,R(X.legs)) achieve("Bawk","your shoes turned evil. dance with them.") elseif pet.clothes then say(pet,R(X.clothes)) achieve("Not Just a Jacket","your clothes were tortillas all along.") elseif pet.helmet then say(pet,R(X.helmet)) achieve("Crunch","an evil salad helmet. find ranch.") elseif pet.evilbeans then say(pet,R(X.evilbeans)) else say(pet,R(L.evil)) end end function unEvil(pet) pet.evil=false pet.super=false pet.folds=0 pet.hyperT=nil pet.hugs=0 pet.poison=0 pet.rage=1 pet.hunger=50 pet.love=50 pet.sc=math.min(pet.sc,2.5)
if pet.hl then pet.hl:Destroy() pet.hl=nil end if pet.fire then pet.fire:Destroy() pet.fire=nil end pet.st.TextColor3=WHITE setPrompts(pet,"cute") sparkle(pet.p,GOLD) say(pet,R(L.freed),"hat") end local function goSuper(pet) pet.super=true pet.need=5 pet.hl.FillColor=BLACK pet.hl.OutlineColor=PURP pet.fire.Color=PURP pet.fire.SecondaryColor=BLACK pet.fire.Size=10 boom(pet.p.Position,8) setPrompts(pet,"evil") if not pet.supremo then say(pet,"MASTER... I HAVE FOUND HIM...") achieve("Super Evil","a hat reached 10x. good luck.") end end local function goUltra(pet) pet.ultra=true pet.ultraT=os.clock()
local hl=Instance.new("Highlight") hl.FillColor=GOLD hl.OutlineColor=GOLD hl.FillTransparency=0.6 hl.Parent=pet.p local s=Instance.new("Sparkles") s.SparkleColor=GOLD s.Parent=pet.p boom(pet.p.Position,4) pet.st.TextColor3=GOLD setPrompts(pet,"ultra") achieve("Golden Hat","a hat ate its own burrito!") say(pet,"I ATE MY BURRITO. i am free... and i will protect you.") end local function spawnMini(pet) local m=part(Vector3.new(1.4,0.8,0.8),TAN) m.Shape=Enum.PartType.Cylinder local lt=Instance.new("PointLight") lt.Color=PURP lt.Range=6 lt.Parent=m table.insert(minis,{p=m,pos=pet.pos,t0=os.clock()}) end
local function infect() if inf then return end local ch=plr.Character local hd=ch and ch:FindFirstChild("Head") if not hd then return end local g,l=label(hd,"BURRITO INFECTION 0%",RED,260,40,3) inf={t0=os.clock(),lvl=0,gui=g,lbl=l} end local function cure() if not inf then return end if inf.gui then inf.gui:Destroy() end if inf.hl then inf.hl:Destroy() end local ch=plr.Character local hum=ch and ch:FindFirstChildOfClass("Humanoid") if hum then hum.WalkSpeed=16 end
local hd=ch and ch:FindFirstChild("Head") if hd then local g=label(hd,"...i feel normal again",WHITE,260,40,3) DB:AddItem(g,3) end inf=nil achieve("Cured!","blox-cola works on humans too") end function spawnItem(kind,at) local c=plr.Character local r=c and c:FindFirstChild("HumanoidRootPart") if not r and not at then return end local hit if at then hit=ground(at+Vector3.new(0,5,0),40) else hit=ground(r.Position+Vector3.new(math.random(-80,80),100,math.random(-80,80)),400) end if not hit then return end local f=Instance.new("Part") f.Name=kind f.Anchored=true f.CanCollide=false f.Material=Enum.Material.Neon local col,txt,tcol if kind=="food" then f.Shape=Enum.PartType.Ball f.Size=Vector3.new(1.6,1.6,1.6) col=Color3.fromRGB(220,30,30) txt="FOOD" tcol=Color3.fromRGB(255,220,0)
elseif kind=="poison" then f.Shape=Enum.PartType.Cylinder f.Size=Vector3.new(1.8,1,1) col=TOX txt="POISON" tcol=TOX elseif kind=="churro" then f.Shape=Enum.PartType.Cylinder f.Size=Vector3.new(3,0.5,0.5) f.Material=Enum.Material.SmoothPlastic col=Color3.fromRGB(200,140,60) txt="CHURRO" tcol=Color3.fromRGB(255,170,60) elseif kind=="ranch" then f.Shape=Enum.PartType.Cylinder f.Size=Vector3.new(1.6,0.9,0.9) f.Material=Enum.Material.SmoothPlastic col=Color3.fromRGB(245,245,235) txt="RANCH" tcol=WHITE else f.Shape=Enum.PartType.Cylinder f.Size=Vector3.new(2.2,1.1,1.1) f.Material=Enum.Material.SmoothPlastic col=TAN txt="??? BURRITO" tcol=Color3.fromRGB(255,140,0) DB:AddItem(f,30) end f.Color=col f.CFrame=CFrame.new(hit.Position+Vector3.new(0,1.8,0))*(kind=="food" and CFrame.new() or CFrame.Angles(0,0,math.pi/2)) f.Parent=F local lt=Instance.new("PointLight") lt.Color=kind=="burrito" and tcol or col lt.Range=8 lt.Parent=f label(f,txt,tcol,100,24,2) cnt[kind]=cnt[kind]+1 items[f]=f.CFrame if kind=="burrito" then
local function bp(text,key,off,fn) local q=Instance.new("ProximityPrompt") q.ActionText=text q.ObjectText="??? Burrito" q.KeyboardKeyCode=key q.HoldDuration=0.5 q.RequiresLineOfSight=false q.MaxActivationDistance=10 q.UIOffset=Vector2.new(0,off) q.Parent=f q.Triggered:Connect(function(w) if w==plr and f.Parent and items[f] then fn() items[f]=nil cnt.burrito=cnt.burrito-1 f:Destroy() end end) end bp("Eat",Enum.KeyCode.E,0,infect) bp("Adopt",Enum.KeyCode.R,80,function() adoptBeans(f.CFrame+Vector3.new(0,1,0)) end) bp("Flush",Enum.KeyCode.F,160,function() local fl=part(f.Size,TAN) fl.Shape=Enum.PartType.Cylinder fl.CFrame=f.CFrame label(fl,"glorp... I WILL RETURN",RED,200,30,2) TS:Create(fl,TweenInfo.new(2.5),{CFrame=f.CFrame-Vector3.new(0,4,0),Transparency=1}):Play() DB:AddItem(fl,2.6) flushes=flushes+1 achieve("Don't Flush the Burrito","you flushed it. it will remember.") if flushes>=3 then flushes=0 headMsg("...the ground is gurgling...",PURP,4) task.delay(4,spawnSupremo) end end)
end f.Destroying:Connect(function() if items[f] then items[f]=nil cnt[kind]=cnt[kind]-1 end end) f.Touched:Connect(function(x) if f.Parent and items[f] and plr.Character and x:IsDescendantOf(plr.Character) then if kind=="burrito" then return elseif kind=="poison" and inf then cure() else inv[kind]=inv[kind]+1 end items[f]=nil cnt[kind]=cnt[kind]-1 f:Destroy() end end) end function setPrompts(pet,mode) for _,x in ipairs(pet.prompts) do x:Destroy() end pet.prompts={} local function pr(text,key,gp,off,fn)
local q=Instance.new("ProximityPrompt") q.Name=text q.ActionText=text q.ObjectText=(pet.evil and (pet.super and "SUPER EVIL " or "EVIL ") or pet.ultra and "ULTRA " or "").."("..pet.pers..") "..pet.nm q.KeyboardKeyCode=key q.GamepadKeyCode=gp q.HoldDuration=0 q.RequiresLineOfSight=false q.UIOffset=Vector2.new(0,off) q.Parent=pet.p q.Triggered:Connect(function(w) if w==plr and not pet.dying and not pet.dead then fn() end end) table.insert(pet.prompts,q) end local E,Rk,Fk=Enum.KeyCode.E,Enum.KeyCode.R,Enum.KeyCode.F if mode=="cute" then pr("Feed",E,Enum.KeyCode.ButtonX,0,function() if inv.food<1 then say(pet,"you have no food!! go find some on the map!") return end pet.mem.fed=pet.mem.fed+1 inv.food=inv.food-1 pet.hunger=math.min(100,pet.hunger+35) pet.sc=pet.sc+0.3 pet.spinT=os.clock() sparkle(pet.p,Color3.fromRGB(255,200,0)) say(pet,R(L.happy)) end) pr("Pet",Rk,Enum.KeyCode.ButtonY,80,function() pet.mem.pets=pet.mem.pets+1 if pet.beans then pet.sc=math.min(2,pet.sc+0.1) end pet.love=math.min(100,pet.love+25) pet.spinT=os.clock() sparkle(pet.p,Color3.fromRGB(255,120,200)) say(pet,R(L.pat)) end) pr("Hug",Enum.KeyCode.G,Enum.KeyCode.ButtonL1,160,function() pet.mem.hugs=pet.mem.hugs+1 achieve("Hugger","the hats are huggable") if pet.beans then pet.sc=math.min(2,pet.sc+0.1) end pet.love=math.min(100,pet.love+15) pet.spinT=os.clock() sparkle(pet.p,Color3.fromRGB(255,120,200)) say(pet,pet.beans and "...hug... back..." or "hug!! <3") end)
elseif mode=="evil" then if pet.tail then pr("Say Cool Tail",E,Enum.KeyCode.ButtonX,0,function() local r=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not r then return end local d=pet.p.Position-r.Position local lv=r.CFrame.LookVector if Vector3.new(lv.X,0,lv.Z).Unit:Dot(Vector3.new(d.X,0,d.Z).Unit)<0.4 then say(pet,"youre not even LOOKING at me.") return end saveTail(pet) end) elseif pet.shoes then pr("Dance",E,Enum.KeyCode.ButtonX,0,function() X.cure(pet,"...wait. you WANT to dance? ...BAWK!! (happy bawk)","Dance Partner","you danced with your evil shoes") end) elseif pet.clothes then pr("Fold",E,Enum.KeyCode.ButtonX,0,function() X.fold(pet) end) elseif pet.helmet then pr("Pour Ranch",E,Enum.KeyCode.ButtonX,0,function() if inv.ranch<1 then say(pet,"you need RANCH. its on the map somewhere. crunch.") return end inv.ranch=inv.ranch-1 X.cure(pet,"...oh. oh thats actually really good.","Ranch Hand","you poured ranch on an evil salad helmet") end) else pr("Feed Poison",E,Enum.KeyCode.ButtonX,0,function() if inv.poison<1 then say(pet,R(L.nopoison)) return end pet.mem.poison=pet.mem.poison+1 inv.poison=inv.poison-1 pet.poison=pet.poison+1 pet.stun=os.clock()+1.2 sparkle(pet.p,PURP) pet.hl.FillColor=(pet.super and BLACK or RED):Lerp(PURP,pet.poison/pet.need) say(pet,R(L.poisoned)) if pet.poison>=pet.need then die(pet) end end) pr("Throw Churro",Enum.KeyCode.T,Enum.KeyCode.ButtonR1,320,function() X.churro(pet) end) end pr("Pet",Rk,Enum.KeyCode.ButtonY,80,function() pet.flicker=os.clock()+1.2 pet.sc=pet.sc+0.1 say(pet,R(L.evilpet),"hat") end) pr("Slap",Fk,Enum.KeyCode.ButtonB,160,function() achieve("Burrito Slapper","nobody has EVER slapped a burrito") pet.mem.slaps=pet.mem.slaps+1 pet.stun=os.clock()+1 pet.sc=math.max(1,pet.sc-0.4) pet.rage=pet.rage*1.1 beans(pet.p.Position) say(pet,R(L.slap)) if pet.sc<3 then unEvil(pet) end end) pr("Hug",Enum.KeyCode.G,Enum.KeyCode.ButtonL1,240,function()
if pet.evilbeans then X.twin(pet) return end local now=os.clock() pet.mem.hugs=pet.mem.hugs+1 pet.hugs=(pet.hugs or 0)+1 local hg=pet.hugs local pink=Color3.fromRGB(255,120,200) achieve("Hugger","you hugged a burrito. why.") pet.stun=now+3 pet.embarrass=hg<=2 and now+7 or 0 if hg>=3 then pet.flicker=now+3 end pet.hl.FillColor=(pet.super and BLACK or RED):Lerp(pink,math.min(1,hg/5)) if pet.fire then pet.fire.Size=math.max(1,(pet.super and 10 or 5)*(1-hg/5)) end sparkle(pet.p,pink) if pet.supremo then say(pet,"...no one... has ever... hugged our toe...","hat") if hg>=5 then redeem(pet) end return end if hg==1 then say(pet,"...it's... warm...","hat") task.delay(3,function() if not pet.dead and pet.evil then say(pet,"...NO. I AM EVIL. I DO NOT HUG.") end end) elseif hg==2 then say(pet,"...why do you keep DOING that...") elseif hg==3 then say(pet,"...i don't know what this feeling is...","hat")
elseif hg==4 then say(pet,"for 10 years... nobody... ever...") beans(pet.p.Position) task.delay(1.5,function() if not pet.dead and pet.evil then say(pet,"I'M STILL HERE! KEEP GOING!","hat") end end) else adoptBeans(pet.p.CFrame+Vector3.new(0,3,0)) unEvil(pet) say(pet,"you didn't give up on me...","hat") achieve("True Ending","5 hugs. the burrito became good. everyone wins.") end end) elseif mode=="inside" then pr("Untuck",E,Enum.KeyCode.ButtonX,0,function() X.untuck(pet) end) pr("Eat It Back",Rk,Enum.KeyCode.ButtonY,80,function() X.eatBack(pet) end) elseif mode=="fox" then pr("Pet",Rk,Enum.KeyCode.ButtonY,0,function() sparkle(pet.p,Color3.fromRGB(255,140,0)) pet.spinT=os.clock() say(pet,R(X.fox)) end) pr("Hug",Enum.KeyCode.G,Enum.KeyCode.ButtonL1,80,function() achieve("Hugger","the hats are huggable") pet.spinT=os.clock() say(pet,"ding! (thats a happy ding)") end)
elseif mode=="ultra" then pr("Pet",Rk,Enum.KeyCode.ButtonY,0,function() sparkle(pet.p,GOLD) pet.spinT=os.clock() say(pet,R(L.ultra)) end) pr("Hug",Enum.KeyCode.G,Enum.KeyCode.ButtonL1,80,function() achieve("Hugger","the hats are huggable") sparkle(pet.p,GOLD) pet.spinT=os.clock() say(pet,"...thank you. for everything.") end) end end function mk(h,i,head,acc,kind) local p=h:Clone() for _,d in ipairs(p:GetDescendants()) do if d:IsA("JointInstance") or d:IsA("WeldConstraint") or d:IsA("Attachment") then d:Destroy() end end p.Anchored=false p.CanCollide=true p.CFrame=h.CFrame p.Parent=F
local m=p:FindFirstChildOfClass("SpecialMesh") local g=Instance.new("BillboardGui") g.Size=UDim2.new(0,230,0,70) g.AlwaysOnTop=true g.MaxDistance=150 g.Parent=p local s=Instance.new("TextLabel") s.Size=UDim2.new(1,0,0.6,0) s.BackgroundColor3=WHITE s.TextColor3=BLACK s.TextScaled=true s.Font=Enum.Font.FredokaOne s.Text="" s.Visible=false s.Parent=g Instance.new("UICorner").Parent=s local st=Instance.new("TextLabel") st.Size=UDim2.new(1,0,0.4,0) st.Position=UDim2.new(0,0,0.6,0) st.BackgroundTransparency=1 st.TextColor3=WHITE st.TextStrokeTransparency=0 st.TextScaled=true st.Font=Enum.Font.GothamBold st.Text="" st.Parent=g local pet={pers=kind=="supremo" and "chaotic" or kind=="beans" and "sweet" or kind=="churro" and "shy" or kind=="evilbeans" and "grumpy" or PKEYS[math.random(#PKEYS)],mem={fed=0,pets=0,hugs=0,slaps=0,poison=0,ate=0},made=os.clock(),p=p,m=m,nm=kind=="beans" and "Beans" or kind=="evilbeans" and "Evil Beans" or kind=="churro" and "Churro Jr." or kind=="supremo" and "EL BURRITO SUPREMO" or h.Parent.Name,acc=acc,innocent=kind=="innocent" or kind=="beans" or kind=="churro",tail=kind=="tail",churro=kind=="churro",shoes=kind=="legs",clothes=kind=="clothes",helmet=kind=="helmet",evilbeans=kind=="evilbeans",beans=kind=="beans",supremo=kind=="supremo",s0=p.Size,ms0=m and m.Scale,rot=head and (head.CFrame:Inverse()*h.CFrame).Rotation or CFrame.new(),sc=1,hunger=60,love=60,poison=0,need=3,rage=1,survive=0,evil=false,falling=true,i=i,say=s,st=st,g=g,t0=0,nxt=os.clock()+math.random(5,9),blink=0,stun=0,lunge=0,flicker=0,hitT=0,spinT=-10,yaw=0,dyaw=0,ph=0,amp=0,wnext=0,prompts={},parts={},w={},pu={},br={},legs={},feet={},arms={},xw={},xp={},teeth={}} setPrompts(pet,"cute") table.insert(pets,pet) task.delay(1.5,function() if p.Parent then
p.Anchored=true p.CanCollide=false pet.pos=p.Position pet.born=os.clock() local function add(q) table.insert(pet.parts,q) return q end for k=1,2 do pet.w[k]=add(part(Vector3.one,WHITE,nil,true)) pet.pu[k]=add(part(Vector3.one,BLACK,nil,true)) pet.br[k]=add(part(Vector3.one,BLACK)) pet.legs[k]=add(part(Vector3.one,LIMB)) pet.feet[k]=add(part(Vector3.one,LIMB,nil,true)) pet.arms[k]=add(part(Vector3.one,LIMB)) pet.xw[k]=add(part(Vector3.one,PURP,Enum.Material.Neon,true)) pet.xp[k]=add(part(Vector3.one,BLACK,nil,true)) end pet.mo=add(part(Vector3.one,BLACK,nil,true)) for k=1,6 do pet.teeth[k]=add(part(Vector3.one,Color3.fromRGB(235,225,190))) end pet.falling=false if pet.evilbeans then pet.tophat=add(part(Vector3.one,BLACK)) pet.tophat.Shape=Enum.PartType.Cylinder pet.brim=add(part(Vector3.one,BLACK)) pet.brim.Shape=Enum.PartType.Cylinder goEvil(pet) elseif pet.supremo then pet.sc=6 goEvil(pet) goSuper(pet) pet.need=8 say(pet,R(L.supremo)) achieve("THE APOCALYPSE","you flushed 3 burritos. EL BURRITO SUPREMO has risen.") else say(pet,pet.beans and "*sniff* ...you saved me? im Beans." or pet.churro and "*crumbles* ...you looked at me. im Churro Jr." or pet.tail and "...sssswish. finally. im not BEHIND you anymore." or pet.shoes and "bawk! i mean... hi!" or pet.clothes and "...im just a jacket. totally normal jacket." or pet.helmet and "crunch. hello. have you had water today?" or pet.innocent and R(L.innocent) or R(L.born)) if pet.innocent and not pet.beans and not pet.churro then achieve("Innocent Hat","one of your hats has no burrito!") end end end end)
end local function wander(pet,pos,rpos,now) if now>pet.wnext then pet.wnext=now+math.random(3,7) if math.random()<0.35 then pet.wt=nil else local a=math.random()*math.pi*2 local rr=math.random(6,22) pet.wt=rpos+Vector3.new(math.cos(a)*rr,0,math.sin(a)*rr) end end if pet.wt then return pet.wt,9 end return pos,0 end function X.kindOf(a,h) local n=a.Name:lower() local at=a.AccessoryType local T=Enum.AccessoryType if n:find("tail") or h:FindFirstChild("WaistBackAttachment") or at==T.Waist then return "tail" end if at==T.LeftShoe or at==T.RightShoe or n:find("shoe") or n:find("boot") or n:find("sneaker") or n:find("sock") then return "legs" end
if at==T.Jacket or at==T.Sweater or at==T.Shirt or at==T.TShirt or at==T.Pants or at==T.Shorts or at==T.DressSkirt or h:FindFirstChildOfClass("WrapLayer") then return "clothes" end if n:find("helmet") or n:find("mask") or (h.Size.X>2.4 and h.Size.Y>2.4 and h.Size.Z>2.2) then return "helmet" end if math.random()<0.25 then return "innocent" end end function X.cure(pet,msg,ach,desc) release(pet) unEvil(pet) pet.innocent=true sparkle(pet.p,GOLD) say(pet,msg,"hat") achieve(ach,desc) end function X.fold(pet) pet.folds=(pet.folds or 0)+1 sparkle(pet.p,WHITE) if pet.folds==1 then say(pet,"...did you just... FOLD me?","hat") elseif pet.folds==2 then say(pet,"...nobody folds me. they just throw me on the chair...","hat")
else X.cure(pet,"...i feel... so organized...","Fold Your Clothes","you folded an evil jacket") end end function X.unwrap(pet) local tw=pet.twrap if not tw then return end if tw.tort then tw.tort:Destroy() end if eating==tw.ch then eating=nil end if tw.r.Parent then tw.r.CFrame=tw.from tw.r.Anchored=false end tw.hum.WalkSpeed=16 tw.hum.JumpPower=50 pet.twrap=nil end function X.tortilla(tw) local tp=part(Vector3.new(4,3.6,3.6),TAN) tp.Shape=Enum.PartType.Cylinder tp.CFrame=CFrame.new(tw.r.Position-Vector3.new(0,0.75,0))*CFrame.Angles(0,0,math.pi/2)
label(tp,"mmf!! (with lettuce)",Color3.fromRGB(120,220,80),220,26,3) tw.tort=tp end function X.churro(pet) if inv.churro<1 then say(pet,"no churro? ...good.") return end inv.churro=inv.churro-1 local now=os.clock() if pet.hyperT and now<pet.hyperT then X.confetti(pet) return end pet.hyperT=now+10 pet.stun=now+10 say(pet,"WAIT IM NOT EVIL ANYMORE IM JUST SO HAPPY WHAT IS SUGAR","hat") achieve("Churrito","you threw a churro into a burrito") task.delay(10,function() if not pet.dead and pet.evil and not pet.dying then unEvil(pet) say(pet,"...zzz... *sugar crash* ...i feel cute again.","hat") end end) end
function X.confetti(pet) local pos=pet.p.Position boom(pos,6) ghost(pet,"...that was the best day of my life.") for n=1,40 do local b=part(Vector3.one*0.4,Color3.fromHSV(math.random(),0.8,1),Enum.Material.Neon) b.Anchored=false b.CanCollide=true b.CustomPhysicalProperties=PhysicalProperties.new(0.01,0.3,0.5) b.Position=pos b.AssemblyLinearVelocity=Vector3.new(math.random(-40,40),math.random(30,60),math.random(-40,40)) DB:AddItem(b,6) end clean(pet) achieve("Cinnamon Confetti","two churros. sugar overload. beautiful.") end function X.untuck(pet) local e=pet.eat if not e or e.done then return end local d=pet.pos-e.r.Position d=Vector3.new(d.X,0,d.Z) d=d.Magnitude>0.1 and d.Unit or Vector3.new(1,0,0) local sz=pet.p.Size.Magnitude*0.5
release(pet) if e.r.Parent then e.r.CFrame=CFrame.new(pet.pos+d*(sz+3)) end beans(pet.pos) pet.stun=os.clock()+3 setPrompts(pet,"evil") say(pet,"NOOOO NOT THE TUCK!!") task.delay(2,function() if not pet.dead then say(pet,"...nobody... saw that... right?") end end) achieve("Every Trap Has a Tuck","you untucked a burrito from the inside") end function X.eatBack(pet) local e=pet.eat if not e or e.done then return end e.bites=(e.bites or 0)+1 pet.sc=math.max(1,pet.sc-0.8) say(pet,e.bites==1 and "...are you EATING MY BEANS?!" or "THOSE ARE MY BEAN ORGANS!!")
if e.bites>=3 then local pos=pet.pos release(pet) clean(pet) local hit=ground(pos+Vector3.new(0,5,0),40) local bl=part(Vector3.new(6,0.2,6),TAN) bl.CanCollide=true bl.Position=(hit and hit.Position or pos)+Vector3.new(0,0.1,0) label(bl,"cozy tortilla blanket (very embarrassed)",TAN,280,30,2) DB:AddItem(bl,60) headMsg("...youre kind of cozy actually.",WHITE,4) achieve("Uno Reverse","it ate you. you ate it back.") end end function X.twin(pet) pet.evilbeans=false for _,q in ipairs({pet.tophat,pet.brim}) do if q then q.Anchored=false q.CanCollide=true DB:AddItem(q,30) end end if pet.tophat then label(pet.tophat,"free top hat :)",WHITE,160,24,1.5) end
pet.tophat=nil pet.brim=nil unEvil(pet) pet.beans=true pet.innocent=true pet.nm="Beans (twin)" setPrompts(pet,"cute") say(pet,"...ive waited my whole life for someone to say sorry...","hat") achieve("Sorry From All Of Us","you hugged evil beans. now there are two beans.") end function X.spawnEvilBeans() local r=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not r or not F.Parent then return end local a=math.random()*math.pi*2 local hit=ground(r.Position+Vector3.new(math.cos(a)*18,60,math.sin(a)*18),200) if not hit then return end headMsg("...something is coming up from the sewers...",PURP,4)
local md,tp=template("Evil Beans",CFrame.new(hit.Position+Vector3.new(0,3,0)),Vector3.new(2,1.1,1.1)) tp.Color=Color3.fromRGB(150,100,60) mk(tp,#pets+1,nil,nil,"evilbeans") md:Destroy() end function X.goFox(pet) pet.fox=true pet.tail=false pet.innocent=true pet.sc=2.5 local hl=Instance.new("Highlight") hl.FillColor=Color3.fromRGB(255,140,0) hl.OutlineColor=WHITE hl.FillTransparency=0.6 hl.Parent=pet.p local sp=Instance.new("Sparkles") sp.SparkleColor=Color3.fromRGB(255,140,0) sp.Parent=pet.p setPrompts(pet,"fox") say(pet,"ding! ...POW.") achieve("What Does It Say","a happy tail became a fox") end function X.goHug(pet)
